    if n <= 2:
        return 0
    # Only odd numbers: index i represents number 2*i+1
    m = (n - 1) // 2
    sieve = bytearray([1]) * (m + 1)
    sieve[0] = 0  # 1 is not prime
    limit = int(n**0.5)
    for i in range(1, (limit - 1) // 2 + 1):
        if sieve[i]:
            # 2*i+1 squared = 4*i^2 + 4*i + 1, which corresponds to odd index 2*i*(i+1)
            start = 2 * i * (i + 1)
            step = 2 * i + 1
            for j in range(start, m + 1, step):
                sieve[j] = 0
    # Count includes 2 (the only even prime)
    return 1 + sum(sieve)

